class TwoStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        available = {}

        for symbol in self.symbols:
            if symbol in data.Bars:
                available[symbol] = data.Bars[symbol]

        for symbol, bar in available.items():
            close = float(bar.Close)

            if symbol in self.previous_closes:
                if symbol == self.aapl:
                    if close < self.previous_closes[symbol]:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0

            self.previous_closes[symbol] = close

            if symbol == self.spy:
                self.spy_closes.Add(close)

            if symbol == self.aapl:
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

        if not all(symbol in available for symbol in self.symbols):
            return

        spy_cross_up = False
        spy_cross_down = False

        if self.spy_closes.Count >= 101:
            current_sma = sum(
                float(self.spy_closes[i]) for i in range(100)
            ) / 100.0

            previous_sma = sum(
                float(self.spy_closes[i]) for i in range(1, 101)
            ) / 100.0

            if not hasattr(self, "previous_spy_sma"):
                self.previous_spy_sma = previous_sma
            else:
                spy_cross_up = (
                    self.previous_spy_sma <= previous_sma
                    and current_sma > previous_sma
                )
                spy_cross_down = (
                    self.previous_spy_sma >= previous_sma
                    and current_sma < previous_sma
                )

            self.previous_spy_sma = current_sma

        if self.strategy_a_lot > 0 and spy_cross_down:
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="Strategy A sell"
            )
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.IsReady:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="Strategy B sell"
                )
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_cross_up:
            close = float(available[self.spy].Close)
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value / close)

            if quantity > 0:
                self.MarketOrder(
                    self.spy,
                    quantity,
                    tag="Strategy A buy"
                )
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            cash_required = 20000.0

            if float(self.Portfolio.Cash) >= cash_required:
                close = float(available[self.aapl].Close)
                quantity = int(cash_required / close)

                if quantity > 0:
                    self.MarketOrder(
                        self.aapl,
                        quantity,
                        tag="Strategy B buy"
                    )
                    self.strategy_b_lot = quantity
