        for symbol in symbols:
            if not data.Bars.ContainsKey(symbol):
                bars[symbol] = None
            else:
                bars[symbol] = data.Bars[symbol]

        for symbol in symbols:
            bar = bars[symbol]
            if bar is None:
                continue

            close = float(bar.Close)
            previous_close = self.previous_close[symbol]

            if previous_close is not None:
                if close < previous_close:
                    self.red_streak[symbol] += 1
                else:
                    self.red_streak[symbol] = 0

            self.previous_close[symbol] = close

            if symbol == self.spy:
                self.sma.Update(bar.EndTime, close)
            elif symbol == self.aapl:
                self.rsi.Update(bar.EndTime, close)

        if self.IsWarmingUp:
            if self.sma.IsReady:
                self.previous_spy_sma = float(self.sma.Current.Value)
            return

        if any(bars[symbol] is None for symbol in symbols):
            if self.sma.IsReady:
                self.previous_spy_sma = float(self.sma.Current.Value)
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_sma_ready = self.sma.IsReady and self.previous_spy_sma is not None
        upward_cross = False
        downward_cross = False

        if spy_sma_ready:
            current_sma = float(self.sma.Current.Value)
            previous_close = self.previous_close[self.spy]
            if previous_close is not None:
                upward_cross = (
                    previous_close <= self.previous_spy_sma
                    and spy_close > current_sma
                )
                downward_cross = (
                    previous_close >= self.previous_spy_sma
                    and spy_close < current_sma
                )

        rsi_ready = self.rsi.IsReady
        rsi_above_60 = rsi_ready and float(self.rsi.Current.Value) > 60

        if self.strategy_a_lot > 0 and downward_cross:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and rsi_above_60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and upward_cross:
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.red_streak[self.aapl] >= 3:
            if float(self.Portfolio.Cash) >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

        if self.sma.IsReady:
            self.previous_spy_sma = float(self.sma.Current.Value)
