from AlgorithmImports import *


class IndependentSpyAaplStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_buy_pending = False
        self.strategy_a_sell_pending = False
        self.strategy_b_buy_pending = False
        self.strategy_b_sell_pending = False

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        upward_cross = False
        downward_cross = False

        if spy_bar is not None:
            current_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None

            if (
                current_spy_sma is not None
                and self.prev_spy_close is not None
                and self.prev_spy_sma is not None
            ):
                upward_cross = (
                    self.prev_spy_close <= self.prev_spy_sma
                    and spy_bar.Close > current_spy_sma
                )
                downward_cross = (
                    self.prev_spy_close >= self.prev_spy_sma
                    and spy_bar.Close < current_spy_sma
                )

            self.prev_spy_close = spy_bar.Close
            if current_spy_sma is not None:
                self.prev_spy_sma = current_spy_sma

        if aapl_bar is not None:
            if self.prev_aapl_close is not None:
                if aapl_bar.Close < self.prev_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.prev_aapl_close = aapl_bar.Close

        if not all(symbol in data.Bars for symbol in self.symbols):
            return

        if self.IsWarmingUp:
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if (
            self.strategy_a_lot > 0
            and not self.strategy_a_sell_pending
            and downward_cross
        ):
            self.strategy_a_sell_pending = True
            self.MarketOrder(
                self.spy,
                -self.strategy_a_lot,
                tag="STRATEGY_A_SELL"
            )
        elif (
            self.strategy_a_lot == 0
            and not self.strategy_a_buy_pending
            and upward_cross
        ):
            shares = int(
                (self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close
            )
            if shares > 0:
                self.strategy_a_buy_pending = True
                self.MarketOrder(
                    self.spy,
                    shares,
                    tag="STRATEGY_A_BUY"
                )

        if (
            self.strategy_b_lot > 0
            and not self.strategy_b_sell_pending
            and self.aapl_rsi.Current.Value > 60
        ):
            self.strategy_b_sell_pending = True
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_lot,
                tag="STRATEGY_B_SELL"
            )
        elif (
            self.strategy_b_lot == 0
            and not self.strategy_b_buy_pending
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        ):
            shares = int(20000 / aapl_bar.Close)
            if shares > 0:
                self.strategy_b_buy_pending = True
                self.MarketOrder(
                    self.aapl,
                    shares,
                    tag="STRATEGY_B_BUY"
                )

    def OnOrderEvent(self, order_event):
        if order_event.Status not in (
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ):
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        fill_quantity = int(order_event.FillQuantity)

        if order.Tag == "STRATEGY_A_BUY":
            self.strategy_a_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_buy_pending = False

        elif order.Tag == "STRATEGY_A_SELL":
            self.strategy_a_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_sell_pending = False
                if self.strategy_a_lot <= 0:
                    self.strategy_a_lot = 0

        elif order.Tag == "STRATEGY_B_BUY":
            self.strategy_b_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_buy_pending = False

        elif order.Tag == "STRATEGY_B_SELL":
            self.strategy_b_lot += fill_quantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_sell_pending = False
                if self.strategy_b_lot <= 0:
                    self.strategy_b_lot = 0
